"""Production Operations Contract for one LP project.

This module is intentionally provider-neutral and persistence-neutral.  It is
the backend contract that a future database, API, or operations UI can call.
The important invariants live here rather than in a dashboard:

* projects move only through declared, gated transitions;
* drafts and releases are separate, and releases are immutable snapshots;
* revisions create a new version and must be regenerated by the Engine;
* Safety, rights, QA, and human approval are never bypassed; and
* simulation/test records are visibly non-production.
"""

from __future__ import annotations

from copy import deepcopy
from dataclasses import asdict, dataclass, field
from datetime import UTC, datetime
import hashlib
import json
from typing import Any, Callable, Mapping
from uuid import uuid4


PROJECT_STATUSES = (
    "NEW",
    "RESEARCH_READY",
    "SALES_SAMPLE_GENERATING",
    "SALES_SAMPLE_READY",
    "HEARING_REQUIRED",
    "HEARING_IN_PROGRESS",
    "FINALIZATION_READY",
    "FINAL_GENERATING",
    "CLIENT_REVIEW",
    "REVISION_REQUIRED",
    "REVISION_GENERATING",
    "QA_REVIEW",
    "APPROVAL_REQUIRED",
    "RELEASE_CANDIDATE",
    "PUBLISH_READY",
    "DELIVERED",
    "ARCHIVED",
)

TRANSITIONS: dict[str, tuple[str, ...]] = {
    "NEW": ("RESEARCH_READY",),
    "RESEARCH_READY": ("SALES_SAMPLE_GENERATING",),
    "SALES_SAMPLE_GENERATING": ("SALES_SAMPLE_READY",),
    "SALES_SAMPLE_READY": ("HEARING_REQUIRED", "FINALIZATION_READY"),
    "HEARING_REQUIRED": ("HEARING_IN_PROGRESS",),
    "HEARING_IN_PROGRESS": ("FINALIZATION_READY",),
    "FINALIZATION_READY": ("FINAL_GENERATING",),
    "FINAL_GENERATING": ("CLIENT_REVIEW",),
    "CLIENT_REVIEW": ("REVISION_REQUIRED", "APPROVAL_REQUIRED"),
    "REVISION_REQUIRED": ("REVISION_GENERATING",),
    "REVISION_GENERATING": ("QA_REVIEW",),
    "QA_REVIEW": ("CLIENT_REVIEW", "APPROVAL_REQUIRED"),
    "APPROVAL_REQUIRED": ("RELEASE_CANDIDATE",),
    "RELEASE_CANDIDATE": ("PUBLISH_READY",),
    "PUBLISH_READY": ("DELIVERED",),
    "DELIVERED": ("ARCHIVED", "REVISION_REQUIRED"),
    "ARCHIVED": ("REVISION_REQUIRED",),
}

REVISION_TYPES = (
    "FACT_UPDATE",
    "COPY_PREFERENCE",
    "ASSET_REPLACEMENT",
    "DESIGN_PREFERENCE",
    "STRUCTURAL_CHANGE",
    "BUSINESS_CHANGE",
    "OUT_OF_SCOPE",
)

APPROVAL_TYPES = (
    "CONTENT_APPROVAL",
    "DESIGN_APPROVAL",
    "RIGHTS_APPROVAL",
    "RELEASE_APPROVAL",
)

ARTIFACT_TYPES = (
    "research_input",
    "evidence_ledger",
    "strategy",
    "IA",
    "copy",
    "art_direction",
    "render_spec",
    "HTML",
    "captures",
    "QA",
    "hearing_plan",
    "hearing_answers",
    "finalization_spec",
    "revision_request",
    "approval",
    "delivery_package",
)

EXCEPTION_STATUSES = (
    "WAITING_FOR_CLIENT",
    "WAITING_FOR_RIGHTS",
    "WAITING_FOR_DOCUMENT",
    "QA_FAILED",
    "SAFETY_BLOCKED",
    "APPROVAL_REQUIRED",
)


class OperationsError(RuntimeError):
    """Base error for an invariant violation in the operations contract."""


class IllegalTransitionError(OperationsError):
    """Raised when a project tries to skip or reverse a lifecycle state."""


class GateError(OperationsError):
    """Raised when a state transition's required evidence is not complete."""


class ImmutableReleaseError(OperationsError):
    """Raised when code attempts to edit a release instead of making a revision."""


def _now() -> str:
    return datetime.now(UTC).isoformat()


def _id(prefix: str) -> str:
    return f"{prefix}_{uuid4().hex[:12]}"


def _digest(value: Any) -> str:
    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return "sha256:" + hashlib.sha256(payload.encode("utf-8")).hexdigest()


@dataclass
class Project:
    project_id: str
    client_id: str
    company_id: str
    project_status: str = "NEW"
    current_version: str | None = None
    sales_sample_generation_id: str | None = None
    final_generation_id: str | None = None
    hearing_status: str = "NOT_STARTED"
    evidence_status: str = "INCOMPLETE"
    safety_status: str = "UNASSESSED"
    rights_status: str = "UNASSESSED"
    qa_status: str = "UNASSESSED"
    client_review_status: str = "NOT_STARTED"
    release_status: str = "NOT_READY"
    delivery_status: str = "NOT_DELIVERED"
    exception_status: str | None = None
    simulation_mode: bool = False
    rubric_version: str = "unknown"
    reviewer_contract_version: str = "unknown"
    active_release_id: str | None = None
    created_at: str = field(default_factory=_now)
    updated_at: str = field(default_factory=_now)

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass
class ArtifactRecord:
    artifact_id: str
